import type { FsEntry, ProcessRunInit, ProcessRunResult, SessionRepo, SessionUsage } from 'claude-code'
import type { Usage } from '../../types'
import { usageFrom, usageFromFlags } from './facts'
import type { Flag } from './facts'

// $-using: the platform, where skillator's scripts live, and every script call in
// both spellings (design §2). No shell: argv only.

// The part of `$` this file uses. The plugin's `$` (EngineInterface) is one.
export type HostApi = {
  plugin: { root: string }
  env: { get: (name: string) => Promise<string | undefined> }
  process: { run: (argv: readonly string[], init?: ProcessRunInit) => Promise<ProcessRunResult> }
  fs: {
    exists: (path: string) => Promise<boolean>
    read: (path: string) => Promise<string>
    list: (path?: string) => Promise<FsEntry[]>
  }
  session: {
    repo: () => Promise<SessionRepo | null>
    usage: () => Promise<SessionUsage>
    id: () => Promise<string>
  }
}

export type Call = 'pending' | 'pending-kv' | 'pending-machine' | 'meta-assign' | 'meta-decide' | 'meta-decided'
  | 'meta-team-add' | 'meta-team-remove'
  | 'relay-list' | 'relay-chain-status' | 'relay-queue-add' | 'relay-hold' | 'relay-release' | 'relay-hold-status' | 'relay-decide'

const PENDING = 'skills/tickets-zordon/scripts/pending'
const META = 'skills/tickets-zordon/scripts/ticket-meta'
const RELAY = 'skills/relay-morpheus/hooks/relay-morpheus'
const MARKER = '/' + META + '.sh'

// Forward slashes, no trailing one: both hosts take them, and joins stay simple.
const norm = (p: string) => p.replace(/\\/g, '/').replace(/(.)\/+$/, '$1')
const up = (p: string, n: number) => {
  let s = norm(p)
  for (let i = 0; i < n; i++) s = s.slice(0, Math.max(s.lastIndexOf('/'), 0)) || s
  return s
}

export async function isWindows($: HostApi): Promise<boolean> {
  return (await $.env.get('OS')) === 'Windows_NT'
}

// One table: each call's script and its words for the sh and the ps1 port.
// args: meta-assign/meta-decide [id, @handle]; meta-decided [id]; meta-team-add
// [@handle, name, emails comma-joined]; meta-team-remove [@handle]; relay-chain-status and
// relay-queue-add [RUN-id]; relay-hold [reason]; relay-decide [level line]; others none.
const TABLE: Record<Call, { script: string; sh: (a: string[]) => string[]; ps: (a: string[]) => string[] }> = {
  'pending':            { script: PENDING, sh: a => a, ps: a => a },
  'pending-kv':         { script: PENDING, sh: a => ['--kv', ...a], ps: a => ['--kv', ...a] },
  'pending-machine':    { script: PENDING, sh: a => ['--machine', ...a], ps: a => ['--machine', ...a] },
  'meta-assign':        { script: META, sh: a => ['assign', ...a], ps: a => ['assign', ...a] },
  'meta-decide':        { script: META, sh: a => ['decide', ...a], ps: a => ['decide', ...a] },
  'meta-decided':       { script: META, sh: a => ['decided', ...a], ps: a => ['decided', ...a] },
  'meta-team-add':      { script: META, sh: a => ['team', 'add', ...a], ps: a => ['team', 'add', ...a] },
  'meta-team-remove':   { script: META, sh: a => ['team', 'remove', ...a], ps: a => ['team', 'remove', ...a] },
  'relay-list':         { script: RELAY, sh: () => ['list'], ps: () => ['-Mode', 'list'] },
  'relay-chain-status': { script: RELAY, sh: a => [a[0] ?? '', 'chain', 'status'], ps: a => ['-Mode', 'chain', '-Action', 'status', '-Id', a[0] ?? ''] },
  'relay-queue-add':    { script: RELAY, sh: a => ['queue-run', 'add', a[0] ?? ''], ps: a => ['-Mode', 'queue-run', '-Sub', 'add', '-Id', a[0] ?? ''] },
  'relay-hold':         { script: RELAY, sh: a => ['watchdog', 'hold', a[0] ?? ''], ps: a => ['-Mode', 'watchdog', '-Action', 'hold', '-Reason', a[0] ?? ''] },
  'relay-release':      { script: RELAY, sh: () => ['watchdog', 'release'], ps: () => ['-Mode', 'watchdog', '-Action', 'release'] },
  'relay-hold-status':  { script: RELAY, sh: () => ['watchdog', 'status'], ps: () => ['-Mode', 'watchdog', '-Action', 'status'] },
  'relay-decide':       { script: RELAY, sh: a => ['chain', 'decide', '--level', a[0] ?? ''], ps: a => ['-Mode', 'chain', '-Action', 'decide', '-Text', a[0] ?? ''] },
}

export function argvFor(call: Call, win: boolean, root: string, args: string[]): string[] {
  const t = TABLE[call]
  const base = norm(root) + '/' + t.script
  return win
    ? ['powershell', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', base + '.ps1', ...t.ps(args)]
    : ['sh', base + '.sh', ...t.sh(args)]
}

async function has($: HostApi, root: string): Promise<boolean> {
  try { return await $.fs.exists(root + MARKER) } catch { return false }
}

async function configDir($: HostApi): Promise<string | null> {
  const cfg = await $.env.get('CLAUDE_CONFIG_DIR')
  if (cfg) return norm(cfg)
  const home = (await $.env.get('HOME')) || (await $.env.get('USERPROFILE'))
  return home ? norm(home) + '/.claude' : null
}

// The first that holds skills/tickets-zordon/scripts/ticket-meta.sh: $SKILLATOR_ROOT,
// the plugin folder two up (a repo checkout), then the installPath of
// skillator@skillator in <config dir>/plugins/installed_plugins.json. None: null.
// A136: never the session's repo - any repo opened would otherwise have its own
// scripts run by the band's poll, unasked. Developing in a checkout: set SKILLATOR_ROOT.
export async function skillatorRoot($: HostApi): Promise<string | null> {
  const env = await $.env.get('SKILLATOR_ROOT')
  const tries = [env ? norm(env) : null, up($.plugin.root, 2)]
  for (const t of tries) if (t && await has($, t)) return t
  const cfg = await configDir($)
  if (!cfg) return null
  let installed: unknown
  try { installed = JSON.parse(await $.fs.read(cfg + '/plugins/installed_plugins.json')) } catch { return null }
  const entries = (installed as { plugins?: Record<string, unknown> })?.plugins?.['skillator@skillator']
  if (!Array.isArray(entries)) return null
  for (const e of entries) {
    const p = (e as { installPath?: unknown })?.installPath
    if (typeof p === 'string' && p && await has($, norm(p))) return norm(p)
  }
  return null
}

export const NO_SCRIPTS = 'skillator scripts not found - set SKILLATOR_ROOT'

// Runs one call in the main checkout (the session's cwd outside a repo). Never rejects:
// a command that cannot start or outlasts its budget comes back as code -1, its reason
// in `err`. 30 s budget; `pending --machine` (the band's poll) 15 s.
export async function runCall($: HostApi, call: Call, args: string[]): Promise<{ code: number; out: string; err: string; argv: string[] }> {
  const win = await isWindows($)
  const repo = await $.session.repo()
  const root = await skillatorRoot($)
  if (!root) return { code: 127, out: '', err: NO_SCRIPTS, argv: [] }
  const argv = argvFor(call, win, root, args)
  const timeoutMs = call === 'pending-machine' ? 15000 : 30000
  const init: ProcessRunInit = repo ? { cwd: repo.root, timeoutMs } : { timeoutMs }
  try {
    const r = await $.process.run(argv, init)
    return { code: r.exitCode, out: r.stdout, err: r.stderr, argv }
  } catch (e) {
    return { code: -1, out: '', err: e instanceof Error ? e.message : String(e), argv }
  }
}

// Usage: this session's own host reading first. Only when the host has none, the
// watch-cortana flag files named by THIS session's id (`<id>`, `<id>.weekly` in
// $CLAUDE_USAGE_WATCH_DIR, else $CLAUDE_CONFIG_DIR/handoff-watch, else
// ~/.claude/handoff-watch - the order usage-watch writes them), dated by their mtime.
export async function readUsage($: HostApi, now: number): Promise<Usage> {
  const u = await $.session.usage()
  const cost = u.cost?.usd ?? null
  if (u.rateLimits.length) return usageFrom(u.rateLimits, cost, now)
  const dirEnv = await $.env.get('CLAUDE_USAGE_WATCH_DIR')
  const cfgEnv = await $.env.get('CLAUDE_CONFIG_DIR')
  const home = (await $.env.get('HOME')) || (await $.env.get('USERPROFILE'))
  const dir = dirEnv ? norm(dirEnv) : cfgEnv ? norm(cfgEnv) + '/handoff-watch' : home ? norm(home) + '/.claude/handoff-watch' : null
  const id = await $.session.id()
  if (!dir || !id) return usageFromFlags(null, null, cost)
  let entries: FsEntry[] = []
  try { entries = await $.fs.list(dir) } catch { return usageFromFlags(null, null, cost) }
  const flag = async (name: string): Promise<Flag | null> => {
    const e = entries.find(x => x.name === name && x.kind === 'file')
    if (!e) return null
    try { return { text: await $.fs.read(dir + '/' + name), mtimeMs: e.mtimeMs } } catch { return null }
  }
  return usageFromFlags(await flag(id), await flag(id + '.weekly'), cost)
}

files.hooks/lib/runs.ts:
import type { RunView, Stage } from '../../types'

// Pure: `relay-morpheus list` plus, per run, `relay-morpheus <id> chain status`
// (its `## Chain` and `## Decisions` sections verbatim). chain status carries no
// stage states; a text that also holds the run's `## Stages` table (the run file,
// `resume`) gives exact ones. Otherwise a stage is `open` when the list row names it
// open, `pending` while the run is planned, and `-` (not known) else.

// cmd_list: printf 'RUN-%s  %-42s  %s/%s done' [ '  (stage %s open)' ]
const ROW = /^(RUN-\S+)  (.*?)\s+(\d+)\/(\d+) done(?:  \(stage ([\d,]+) open\))?\s*$/
const BLOCK = /^### (\S+) - stage (\d+) - (.*)$/
const TABLE_ROW = /^\|\s*(\d+)\s*\|([^|]*)\|([^|]*)\|/

type Parsed = { stages: Stage[]; hasChain: boolean; states: Map<number, string>; decisions: string[] }

// A `### Q<k> <state> <time>` block of `## Decisions` (relay-morpheus.sh park). Only
// `open` and `asked` ones still wait on an answer; answered, ruled, moot... do not.
type Q = { k: string; state: string; fields: Map<string, string> }
const Q_HEAD = /^### (Q\d+) (\S+)/

function decisionText(q: Q): string | null {
  if (q.state !== 'open' && q.state !== 'asked') return null
  const f = (name: string) => (q.fields.get(name) ?? '').trim()
  const ticket = f('ticket').split(/\s+/)[0] || '-'
  const what = f('question') || f('reason') || f('header') || 'a decision'
  const parked = f('parked') || 'the run'
  return `${q.k} ${ticket} ${what} - ${parked} waits on it`
}

function parseChain(text: string): Parsed {
  const stages: Stage[] = []
  const states = new Map<number, string>()
  const qs: Q[] = []
  let section = '', cur: Stage | null = null, hasChain = false, q: Q | null = null
  for (const raw of text.split('\n')) {
    const line = raw.replace(/\r$/, '')
    if (line.startsWith('## ')) {
      section = line.slice(3).trim(); cur = null; q = null
      if (section === 'Chain') hasChain = true
      continue
    }
    if (section === 'Decisions') {
      if (line.startsWith('### ')) {
        const h = Q_HEAD.exec(line)
        q = h ? { k: h[1]!, state: h[2]!, fields: new Map() } : null
        if (q) qs.push(q)
        continue
      }
      // Unindented `name: value` lines only: options are indented.
      const fv = /^([a-z]+): (.*)$/.exec(line)
      if (q && fv && !q.fields.has(fv[1]!)) q.fields.set(fv[1]!, fv[2]!)
      continue
    }
    if (section === 'Stages') {
      const t = TABLE_ROW.exec(line)
      if (t) states.set(Number(t[1]), t[3]!.trim() || 'pending')
      continue
    }
    if (section !== 'Chain') continue
    const b = BLOCK.exec(line)
    if (b) {
      const code = b[1]!
      let title = b[3]!.trim()
      if (title.startsWith(code + ' ')) title = title.slice(code.length + 1)
      cur = { n: Number(b[2]), code, ticket: '', title, after: '-', files: '-', state: '' }
      stages.push(cur)
      continue
    }
    if (!cur) continue
    // Unindented fields only: a prompt's lines are indented two spaces.
    const f = /^(tickets|files|after): (.*)$/.exec(line)
    if (!f) continue
    const val = f[2]!.trim()
    if (f[1] === 'tickets') cur.ticket = val.split(' . ').map(p => p.trim().split(/\s+/)[0]!).filter(Boolean).join(' ')
    else if (f[1] === 'files') cur.files = val || '-'
    else cur.after = val || '-'
  }
  const decisions = qs.map(decisionText).filter((d): d is string => d !== null)
  return { stages, hasChain, states, decisions }
}

export function parseRuns(list: string, chains: Record<string, string>): RunView[] {
  const out: RunView[] = []
  let cur: RunView | null = null
  const open = new Map<string, Set<number>>()
  for (const raw of list.split('\n')) {
    const line = raw.replace(/\r$/, '')
    const r = ROW.exec(line)
    if (r) {
      cur = { id: r[1]!, title: r[2]!.trim(), done: Number(r[3]), total: Number(r[4]), owner: null, stages: [], planned: false, decisions: [] }
      open.set(cur.id, new Set((r[5] ?? '').split(',').filter(Boolean).map(Number)))
      out.push(cur)
      continue
    }
    const o = /^\s+owner: (\S+)\s*$/.exec(line)
    if (o && cur) cur.owner = o[1]!
  }
  for (const run of out) {
    const text = chains[run.id]
    if (text === undefined) continue
    const p = parseChain(text)
    const openSet = open.get(run.id) ?? new Set<number>()
    run.planned = p.hasChain && p.stages.length > 0 && run.done === 0 && openSet.size === 0 &&
      [...p.states.values()].every(s => s === 'pending')
    run.decisions = p.decisions
    run.stages = p.stages.map(s => ({
      ...s,
      state: p.states.get(s.n) ?? (openSet.has(s.n) ? 'open' : run.planned ? 'pending' : '-'),
    }))
  }
  return out
}

files.hooks/lib/restore.ts:
import type { ProcessRunInit, ProcessRunResult } from 'claude-code'

// F48, design §9: a CLAUDE.md the baseline harness hid as CLAUDE.md.skillator-hidden
// (an interrupted GREEN run) is put back. Both ~/.claude and $CLAUDE_CONFIG_DIR are
// checked; a folder is touched only while CLAUDE.md is absent AND the hidden file is
// there. `report` (session start) says so and moves nothing, since another session may
// be mid-GREEN with the file hidden on purpose; `restore` (session end) puts it back:
// the text is written in-process ($.fs.write, fast, inside session end's budget) and
// read back to check it, and only then is the hidden copy removed by a host command
// ($.fs cannot delete). A removal that fails or times out leaves CLAUDE.md restored;
// the line then says the hidden copy is left behind, and where. Contract R1b: a
// `<hidden>.owner` naming a live process (a GREEN run still going) blocks the restore,
// as does a check that cannot be made, or an owner file over 6 hours old; a dead
// owner's file goes with the hidden copy.

// The part of `$` this file uses. The plugin's `$` is one.
export type RestoreApi = {
  env: { get: (name: string) => Promise<string | undefined> }
  clock: { now: () => Promise<number> }
  fs: {
    exists: (path: string) => Promise<boolean>
    read: (path: string) => Promise<string>
    write: (path: string, text: string) => Promise<void>
  }
  process: { run: (argv: readonly string[], init?: ProcessRunInit) => Promise<ProcessRunResult> }
  store: { set: (key: string, value: unknown) => Promise<void> }
}

export const HIDDEN = 'CLAUDE.md.skillator-hidden'
const OWNER_EXT = '.owner'                      // <hidden>.owner: the GREEN run holding it
export const RESTORE_NOTE = 'restoreNote'      // $.store key: the lines the next session shows
const OWNER_OLD_S = 6 * 3600                    // an owner file older than this is never restored by itself
const MIN_BUDGET_MS = 1000

const norm = (p: string) => p.replace(/\\/g, '/').replace(/(.)\/+$/, '$1')
const same = (a: string, b: string, win: boolean) => (win ? a.toLowerCase() === b.toLowerCase() : a === b)
const quote = (p: string) => `'${p.replace(/'/g, "''")}'`

function moveArgv(win: boolean, from: string, to: string): string[] {
  return win
    ? ['powershell', '-NoProfile', '-Command', `Move-Item -LiteralPath ${quote(from)} -Destination ${quote(to)}`]
    : ['mv', '-n', from, to]
}

function removeArgv(win: boolean, paths: string[]): string[] {
  return win
    ? ['powershell', '-NoProfile', '-Command', `Remove-Item -LiteralPath ${paths.map(quote).join(', ')}`]
    : ['rm', '-f', '--', ...paths]
}

// Contract R1b: while a GREEN run has CLAUDE.md hidden, the harness keeps
// `<hidden>.owner` = "<pid> <epoch> <winpid>" (winpid `-` when it has none; the older
// "<pid> <epoch>" reads as winpid `-`). The owner at session end: none (no owner file),
// dead, alive, or unknown (the file cannot be read or parsed, the check cannot be run
// or read, or Windows with winpid `-`). On Windows a numeric winpid is checked with
// tasklist (alive iff its output names that pid); elsewhere `kill -0 <pid>`.
type Owner = { state: 'none' }
  | { state: 'dead' | 'alive'; pid: string; epoch: number }
  | { state: 'unknown'; why: string; epoch: number | null }

// `timeout` hands out the check's time only when a check runs.
async function ownerOf($: RestoreApi, owner: string, win: boolean, timeout: () => number): Promise<Owner> {
  if (!await exists($, owner)) return { state: 'none' }
  let text: string
  try { text = await $.fs.read(owner) } catch (e) { return { state: 'unknown', why: errText(e), epoch: null } }
  const f = /^\s*(\d+)\s+(\d+)(?:\s+(\d+|-))?\s*$/.exec(text)
  if (!f) return { state: 'unknown', why: `${OWNER_EXT} is not "<pid> <epoch> <winpid>"`, epoch: null }
  const pid = f[1]!, epoch = Number(f[2]), winpid = f[3] ?? '-'
  const unknown = (why: string): Owner => ({ state: 'unknown', why, epoch })
  if (win && winpid === '-') return unknown(`${OWNER_EXT} names no Windows pid`)
  const timeoutMs = timeout()
  if (timeoutMs < 1) return unknown('no time left in the session end budget')
  if (win) {
    try {
      const r = await $.process.run(['tasklist', '/FI', `PID eq ${winpid}`, '/NH'], { timeoutMs })
      if (r.exitCode !== 0) return unknown(r.stderr.trim() || r.stdout.trim() || `tasklist exit ${r.exitCode}`)
      if (!r.stdout.trim()) return unknown('tasklist said nothing')
      const alive = new RegExp(`(^|\\s)${winpid}(\\s|$)`).test(r.stdout)
      return { state: alive ? 'alive' : 'dead', pid: winpid, epoch }
    } catch (e) {
      return unknown(errText(e))
    }
  }
  try {
    const r = await $.process.run(['sh', '-c', `kill -0 ${pid}`], { timeoutMs })
    if (r.exitCode === 0) return { state: 'alive', pid, epoch }
    const err = r.stderr.trim()
    if (/not permitted/i.test(err)) return { state: 'alive', pid, epoch }   // EPERM: there, another user's
    if (r.exitCode === 126 || r.exitCode === 127) return unknown(err || `exit ${r.exitCode}`)
    return { state: 'dead', pid, epoch }
  } catch (e) {
    return unknown(errText(e))
  }
}

const errText = (e: unknown) => (e instanceof Error ? e.message : String(e))

async function exists($: RestoreApi, p: string): Promise<boolean> {
  try { return await $.fs.exists(p) } catch { return false }
}

// `remainingMs` is session end's budget: not a number, or under a second, counts as a
// second. It is split across the folders to restore, and each host command's timeout
// comes from what is left of it; the note is stored before any removal runs.
export async function restoreClaudeMd($: RestoreApi, mode: 'report' | 'restore', remainingMs = 5000): Promise<string[]> {
  const win = (await $.env.get('OS')) === 'Windows_NT'
  const homeRaw = win
    ? (await $.env.get('USERPROFILE')) || (await $.env.get('HOME'))
    : (await $.env.get('HOME')) || (await $.env.get('USERPROFILE'))
  const home = homeRaw ? norm(homeRaw) : null
  const cfg = await $.env.get('CLAUDE_CONFIG_DIR')
  const dirs: string[] = []
  if (home) dirs.push(home + '/.claude')
  if (cfg && !dirs.some(d => same(d, norm(cfg), win))) dirs.push(norm(cfg))
  const shown = (p: string) => (home && p.length > home.length && same(p.slice(0, home.length + 1), home + '/', win)
    ? '~' + p.slice(home.length) : p)

  const todo: string[] = []
  for (const dir of dirs) if (!await exists($, dir + '/CLAUDE.md') && await exists($, dir + '/' + HIDDEN)) todo.push(dir)

  const lines: string[] = []
  if (mode === 'report') {
    for (const dir of todo) {
      const md = dir + '/CLAUDE.md', argv = moveArgv(win, dir + '/' + HIDDEN, md)
      lines.push(`▲ ${shown(md)} is hidden as ${HIDDEN} - left as is now (a baseline GREEN may be running); it is put back at session end. By hand: ${byHand(argv)}`)
    }
    return lines
  }

  // The budget: what is left is the budget less the larger of the time gone by and the
  // timeouts already handed out (a frozen clock still cannot overspend it).
  const budget = Number.isFinite(remainingMs) && remainingMs >= MIN_BUDGET_MS ? remainingMs : MIN_BUDGET_MS
  const t0 = await nowMs($)
  let given = 0
  const left = async () => Math.max(0, budget - Math.max(given, (await nowMs($)) - t0))
  const take = (ms: number) => { const t = Math.max(0, Math.floor(ms)); given += t; return t }
  const save = async (extra: string[]) => {
    try { await $.store.set(RESTORE_NOTE, [...lines, ...extra]) } catch { /* the log line still says it */ }
  }

  for (let i = 0; i < todo.length; i++) {
    const dir = todo[i]!, md = dir + '/CLAUDE.md', hidden = dir + '/' + HIDDEN
    const cmd = byHand(moveArgv(win, hidden, md))
    const ownerPath = hidden + OWNER_EXT
    const share = (await left()) / (todo.length - i)
    const owner = await ownerOf($, ownerPath, win, () => take(Math.min(2000, share / 2)))
    if (owner.state === 'alive') {
      lines.push(`▲ ${shown(md)} is hidden by a running GREEN run (pid ${owner.pid}) - left alone`)
      continue
    }
    const old = owner.state !== 'none' && owner.epoch !== null && (await nowMs($)) / 1000 - owner.epoch > OWNER_OLD_S
    const then = `Once no GREEN run is going, by hand: ${cmd}; then delete ${ownerPath}`
    if (owner.state === 'unknown') {
      lines.push(`■ ${shown(md)} not restored from ${HIDDEN}: could not check the run holding it (${owner.why})${old ? '; its owner file is over 6 hours old' : ''}. ${then}`)
      continue
    }
    if (owner.state === 'dead' && old) {
      lines.push(`■ ${shown(md)} not restored from ${HIDDEN}: the run holding it (pid ${owner.pid}) is not running, but its owner file is over 6 hours old - not restored by itself. ${then}`)
      continue
    }
    const gone = owner.state === 'dead' ? [hidden, ownerPath] : [hidden]
    lines.push(await restoreOne($, win, md, hidden, gone, shown, save,
      async () => take((await left()) / (todo.length - i))))
  }
  if (lines.length) await save([])
  return lines
}

async function nowMs($: RestoreApi): Promise<number> {
  try { const t = await $.clock.now(); return Number.isFinite(t) ? t : 0 } catch { return 0 }
}

// The move as a person types it: the shell line, or the PowerShell command.
const byHand = (argv: string[]) => (argv[0] === 'mv' ? argv.join(' ') : argv[3]!)

// One folder: write CLAUDE.md from the hidden copy, check it, store the note, then
// remove the copy. `gone` = the hidden copy, and its owner file when there was one:
// removed together. `timeout` = what the removal may take, asked for when it runs.
async function restoreOne($: RestoreApi, win: boolean, md: string, hidden: string, gone: string[],
  shown: (p: string) => string, save: (extra: string[]) => Promise<void>, timeout: () => Promise<number>): Promise<string> {
  const failed = (why: string) =>
    `■ Could not restore ${shown(md)} from ${HIDDEN}: ${why}. The hidden copy is kept at ${hidden}.`
  let text: string
  try { text = await $.fs.read(hidden) } catch (e) { return failed(errText(e)) }
  // Checked again right before the write: CLAUDE.md is never written over.
  if (await exists($, md)) return failed(`${shown(md)} appeared meanwhile - not written over`)
  try { await $.fs.write(md, text) } catch (e) { return failed(errText(e)) }
  let back: string | null = null
  try { back = await $.fs.read(md) } catch { back = null }
  if (back !== text) return failed(`${shown(md)} does not read back as written - compare it with the hidden copy`)

  const argv = removeArgv(win, gone)
  const head = `✓ Restored ${shown(md)} from ${HIDDEN} (an interrupted baseline run left it hidden).`
  // Stored first: should session end be cut short during the removal, the note still says it.
  await save([`${head} ▲ If ${hidden} is still there, remove it by hand: ${argv.join(' ')}`])
  let why = ''
  const ms = await timeout()
  if (ms < 1) why = 'no time left in the session end budget'
  else {
    try {
      const r = await $.process.run(argv, { timeoutMs: ms })
      if (r.exitCode !== 0) why = r.stderr.trim() || r.stdout.trim() || `exit ${r.exitCode}`
    } catch (e) {
      why = errText(e)
    }
  }
  if (!why) for (const p of gone) if (await exists($, p)) { why = `${p} is still there`; break }
  const leftBehind = why ? ` ▲ The hidden copy is left behind at ${hidden}: ${why} - remove it by hand.` : ''
  return `${head}${leftBehind} ran: ${argv.join(' ')}`
}

files.hooks/band.tsx:
import { atom, read, update } from 'claude-code'
import type { Color, EngineInterface, RenderElement, RenderInput } from 'claude-code'
import type { Board, Level, Machine, Usage, Watch, Window } from '../types'
import { ageText, DISK, figure, HOLD_UNKNOWN, isStale, MEM } from './lib/facts'
import { paint } from './paint'

// F48, design §7: the band above the prompt - always on, green when fine - the
// narrow two-line fold, the notes under it, and the status line's text.

const machineA = atom({ plugin: 'ops-board', key: 'machine' } as const, null)
const usageA = atom({ plugin: 'ops-board', key: 'usage' } as const, null)
const watchA = atom({ plugin: 'ops-board', key: 'watch' } as const, { level: 'green', reasons: [] })
const notesA = atom({ plugin: 'ops-board', key: 'notes' } as const, [])
const relayA = atom({ plugin: 'ops-board', key: 'relay' } as const, null)
const boardA = atom({ plugin: 'ops-board', key: 'board' } as const, null)
const narrowA = atom({ plugin: 'ops-board', key: 'narrow' } as const, false)

export const NARROW_COLUMNS = 110
const FACTS_OLD_MS = 3 * 60 * 1000          // a machine poll missed twice: its facts show their age

export type Counts = { open: number; progress: number; blocked: number; decision: number }
export type BandInput = {
  watch: Watch; machine: Machine | null; usage: Usage | null
  relay: string | null              // "RUN-0012 2/4": the first run not all done
  counts: Counts | null; narrow: boolean; cols: number; now: number
}
export type Seg = { text: string; color?: Color; dim?: boolean; inverse?: boolean; drop?: 1 | 2 }

const LEVEL_COLOR: Record<Level, Color> = { green: 'success', amber: 'warning', red: 'error' }
const GLYPH: Record<Level, string> = { green: '●', amber: '▲', red: '■' }

// Open = [ ] [~] [!] [?]; deferred and closed are not open (tickets-zordon, pending).
export function countsOf(board: Board | null): Counts | null {
  if (!board || board.error) return null
  const n = (b: string) => board.tickets.filter(t => t.box === b).length
  return { open: n(' ') + n('~') + n('!') + n('?'), progress: n('~'), blocked: n('!'), decision: n('?') }
}

// The status line: `ops <n> open · 7d <pct>`. A figure past 15 minutes says so; none
// is left out, never a stale one shown as live.
export function statusText(open: number | null, u: Usage | null, now: number): string {
  const head = `ops ${open === null ? '-' : open} open`
  const w = u?.seven
  if (!w) return head
  return `${head} · 7d ${w.pct}%${isStale(w, now) ? ' (stale)' : ''}`
}

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const two = (n: number) => String(n).padStart(2, '0')
function resetsText(iso: string | null): string | null {
  if (!iso) return null
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return null
  return `resets ${DAYS[d.getDay()]} ${two(d.getHours())}:${two(d.getMinutes())}`
}

// One usage window: fresh host figures bare; a stale one, or one from watch-cortana's
// file, dim with its age; none `-`. relay's decision, when known, colours a held window.
function windowSegs(label: string, w: Window | null, now: number, held: boolean): Seg[] {
  if (!w) return [{ text: label + ' ' }, { text: '-', dim: true }]
  if (isStale(w, now) || w.source === 'watch-cortana') return [{ text: label + ' ' }, { text: `${w.pct}% (${ageText(w, now)})`, dim: true }]
  return [{ text: label + ' ' }, { text: `${w.pct}%`, color: held ? 'warning' : 'success' }]
}

function figSegs(label: string, bytes: number | null | undefined, t: typeof DISK | typeof MEM): Seg[] {
  const f = figure(bytes ?? null, t)
  if (f.level === null) return [{ text: label + ' ' }, { text: '?', dim: true }]
  return [{ text: label + ' ' }, { text: f.level === 'amber' ? f.text + ' low' : f.text, color: LEVEL_COLOR[f.level] }]
}

const join = (parts: Seg[][], sep = '  '): Seg[] => parts.flatMap((p, i) => (i ? [{ text: sep, drop: p[0]?.drop }, ...p] : p))
const width = (line: Seg[]) => line.reduce((s, x) => s + x.text.length, 0)

// The red line: why, what is held, how to clear it (mock m-band).
function redLine(w: Watch): Seg[] {
  const disk = w.reasons.some(r => r.startsWith('disk')), mem = w.reasons.some(r => r.startsWith('mem'))
  const fix = disk && mem ? 'Free disk space and memory' : mem ? 'Free memory' : 'Free space'
  return [{ text: ` ■ HOLD  ${w.reasons.join('. ')}. New relay stages and GREEN runs are held. ${fix}, then /ops resume. `, color: 'error', inverse: true }]
}

export function bandSegs(v: BandInput): Seg[][] {
  const { watch: w, machine: m, usage: u, now } = v
  if (w.level === 'red') return [redLine(w)]
  const held = (u?.decision ?? '').startsWith('HOLD')
  const held7 = held && / 7d$/.test(u?.decision ?? '')
  const lead: Seg[] = [{ text: GLYPH[w.level], color: LEVEL_COLOR[w.level] }, { text: ' ops' }]
  const disk = figSegs('disk', m?.diskFree, DISK), mem = figSegs('mem', m?.memFree, MEM)
  const five = windowSegs('5h', u?.five ?? null, now, held && !held7)
  const seven = windowSegs('7d', u?.seven ?? null, now, held7)
  const locks: Seg[] = !m ? [{ text: 'locks ' }, { text: '?', dim: true }]
    : m.locks.length ? [{ text: 'locks ' }, { text: `${m.locks.length} stale`, color: 'warning' }]
    : [{ text: 'locks ' }, { text: 'ok', color: 'success' }]
  const extra: Seg[][] = []
  if (m?.hold) extra.push([{ text: `${m.hold === HOLD_UNKNOWN ? 'held (reason unknown)' : 'held'} - /ops resume to release`, color: 'warning' }])
  if (m && now - m.at > FACTS_OLD_MS) extra.push([{ text: `facts ${Math.floor((now - m.at) / 60000)}m old`, dim: true }])

  if (v.narrow) {
    const c = v.counts
    const counts: Seg[][] = c ? [[{ text: `${c.open} open` },
      ...([['~', c.progress], ['!', c.blocked], ['?', c.decision]] as const)
        .filter(([, n]) => n > 0).flatMap(([b, n]): Seg[] => [{ text: ' ' }, { text: '●' + n, color: paint(b) }])]] : []
    const one = join([lead, ...counts, ...(v.relay ? [[{ text: v.relay }]] : []), disk, mem])
    const amberWords: Seg[][] = m?.locks.length ? [[{ text: 'locks ' }, { text: `${m.locks.length} stale`, color: 'warning' }]] : []
    const second = join([[{ text: "" }], five, seven, ...amberWords, ...extra,
      [{ text: '/pending  /list-tickets  /ops opens the pane', dim: true }]])
    return [one, second]
  }

  const resets = w.level === 'green' && u?.seven && !isStale(u.seven, now) && u.seven.source === 'host'
    ? resetsText(u.seven.resetsAt) : null
  const sevenR: Seg[] = resets ? [...seven, { text: ' ', drop: 1 }, { text: resets, dim: true, drop: 1 }] : seven
  const relay: Seg[][] = v.relay ? [[{ text: 'relay ' + v.relay, drop: 2 }]] : []
  let line = join([lead, disk, mem, five, sevenR, ...relay, locks, ...extra])
  // Too wide: the reset time goes first, then the relay run; past that the Text truncates.
  for (const level of [1, 2] as const) {
    if (width(line) <= v.cols) break
    line = line.filter(s => s.drop !== level)
  }
  return [line]
}

export function bandLines(v: BandInput): string[] {
  return bandSegs(v).map(l => l.map(s => s.text).join(''))
}

// The AbovePrompt hook's body: the band, then the notes, each with its own [ ok ].
export async function renderBand($: EngineInterface, e: RenderInput<'AbovePrompt'>): Promise<RenderElement> {
  const { Box, Text, Button } = $.ui.resolve(e)
  const cols = Math.max(20, e.props.bodyColumns)
  const narrow = (await read($, narrowA)) || (e.viewport !== undefined && e.viewport.columns < NARROW_COLUMNS)
  const v: BandInput = {
    watch: await read($, watchA), machine: await read($, machineA), usage: await read($, usageA),
    relay: await read($, relayA), counts: countsOf(await read($, boardA)), narrow, cols, now: await $.clock.now(),
  }
  const notes = await read($, notesA)
  const seg = (s: Seg) => <Text color={s.color} dimColor={s.dim} inverse={s.inverse}>{s.text}</Text>
  const lines = bandSegs(v).map((l, i) => (
    <Box key={'line:' + i}><Text wrap={v.watch.level === 'red' ? 'wrap' : 'truncate-end'}>{l.map(seg)}</Text></Box>
  ))
  const noteEls = notes.map((n, i) => {
    const rows = n.split('\n')
    const head = rows[0] ?? ''
    const color: Color | undefined = head.startsWith('✓') ? 'success' : head.startsWith('▲') ? 'warning' : head.startsWith('■') ? 'error' : undefined
    return (
      <Box key={'note:' + i} flexDirection="row" gap={2}>
        <Box flexDirection="column">
          <Text wrap="wrap"><Text color={color}>{head.slice(0, 1)}</Text>{head.slice(1)}</Text>
          {rows.slice(1).map(r => <Text dimColor={r.startsWith('  ') && !r.startsWith('    ')} wrap="truncate-end">{r}</Text>)}
        </Box>
        <Button key={'ok:' + i} onPress={() => { void update($, notesA, xs => xs.filter((_, j) => j !== i)) }}>ok</Button>
      </Box>
    )
  })
  return <Box flexDirection="column">{lines}{noteEls}</Box>
}

